const response = $json;
const statusCode = Number(response.statusCode ?? 0);

const errorResult = (code, message, responseStatus) => [{
  json: {
    success: false,
    statusCode: responseStatus,
    error: { code, message },
  },
}];

if (!statusCode) {
  return errorResult(
    'FLOWPILOT_UNAVAILABLE',
    'FlowPilot API is unavailable. Please try again later.',
    503,
  );
}

if (statusCode === 422) {
  return errorResult(
    'VALIDATION_ERROR',
    'Lead payload failed validation.',
    422,
  );
}

if (statusCode < 200 || statusCode >= 300) {
  return errorResult(
    'FLOWPILOT_ERROR',
    'FlowPilot could not analyze the lead.',
    statusCode === 503 ? 503 : 502,
  );
}

const analysis = response.body;
const priorities = new Set(['high', 'medium', 'low']);
const isNonEmptyString = (value) =>
  typeof value === 'string' && value.trim().length > 0;
const isValid =
  analysis &&
  typeof analysis === 'object' &&
  !Array.isArray(analysis) &&
  isNonEmptyString(analysis.category) &&
  priorities.has(analysis.priority) &&
  Number.isInteger(analysis.lead_score) &&
  analysis.lead_score >= 0 &&
  analysis.lead_score <= 100 &&
  isNonEmptyString(analysis.short_summary) &&
  isNonEmptyString(analysis.recommended_action);

if (!isValid) {
  return errorResult(
    'INVALID_FLOWPILOT_RESPONSE',
    'FlowPilot returned an unexpected response.',
    502,
  );
}

const lead = $('Prepare Lead').item.json;

return [{
  json: {
    success: true,
    statusCode: 200,
    lead,
    analysis,
  },
}];

const response = $json;
const processed = $('Sanitize HubSpot Result').item.json;
const statusCode = Number(response.statusCode ?? 0);
const draft = response.body;
const draftError = () => [{
  json: {
    success: false,
    statusCode: 503,
    error: {
      code: 'DRAFT_ERROR',
      message: 'Lead was synchronized but a response draft could not be generated.',
    },
  },
}];

if (statusCode < 200 || statusCode >= 300 || !draft || typeof draft !== 'object' || Array.isArray(draft)) {
  return draftError();
}

const subject = typeof draft.subject === 'string' ? draft.subject.trim() : '';
const body = typeof draft.body === 'string' ? draft.body.trim() : '';
const htmlLike = /<\s*\/?\s*[a-z][^>]*>/i;
if (!subject || !body || subject.length > 160 || body.length > 2000 || /[\r\n]/.test(subject) || htmlLike.test(subject) || htmlLike.test(body)) {
  return draftError();
}

return [{
  json: {
    ...processed,
    draft: { subject, body, status: 'pending_approval' },
  },
}];

const stored = $json;
const prepared = $('Validate Draft Result').item.json;

if (!stored.id || stored.draft_status !== 'pending_approval' || !stored.draft_subject || !stored.draft_body) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'DRAFT_ERROR',
        message: 'Lead was synchronized but the response draft could not be persisted.',
      },
    },
  }];
}

return [{ json: prepared }];

const row = $json;
const prepared = $('Sanitize Draft Persistence').item.json;
const issued = row.issued === true || row.issued === 'true';
const token = typeof row.approval_token === 'string' ? row.approval_token.toLowerCase() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

if (row.error || !issued || Number(row.id) !== Number(prepared.lead_id) || !uuidPattern.test(token) || !row.approval_expires_at) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'APPROVAL_ERROR',
        message: 'Lead was processed but an approval request could not be created.',
      },
    },
  }];
}

return [{
  json: {
    ...prepared,
    approval: { token, expires_at: row.approval_expires_at },
  },
}];

const data = $json;
const recipient = String($env.FLOWPILOT_INTERNAL_EMAIL_TO ?? '').trim();
const sender = String($env.FLOWPILOT_INTERNAL_EMAIL_FROM ?? '').trim();
const approvalBase = String($env.FLOWPILOT_APPROVAL_URL ?? '').trim();
const addressPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

let baseUrl;
try {
  baseUrl = new URL(approvalBase);
} catch {
  baseUrl = null;
}

const validBaseUrl = baseUrl && ['http:', 'https:'].includes(baseUrl.protocol) && !baseUrl.username && !baseUrl.password && !baseUrl.search && !baseUrl.hash;
if (!addressPattern.test(recipient) || !addressPattern.test(sender) || !validBaseUrl || !data.approval?.token || !data.lead_id) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'EMAIL_ERROR',
        message: 'Lead was processed but the internal notification could not be sent.',
      },
    },
  }];
}

const decisionUrl = (decision) => {
  const url = new URL(baseUrl.toString());
  url.searchParams.set('lead_id', String(data.lead_id));
  url.searchParams.set('token', data.approval.token);
  url.searchParams.set('decision', decision);
  return url.toString();
};

const notificationBody = [
  'A lead has completed FlowPilot processing.',
  '',
  `Name: ${data.lead.name}`,
  `Email: ${data.lead.email}`,
  `Company: ${data.lead.company}`,
  `Budget: ${data.lead.budget}`,
  `Priority: ${data.analysis.priority}`,
  `Lead score: ${data.analysis.lead_score}`,
  `Summary: ${data.analysis.short_summary}`,
  `Recommended action: ${data.analysis.recommended_action}`,
  '',
  'Pending lead-response draft',
  `Subject: ${data.draft.subject}`,
  '',
  data.draft.body,
  '',
  'This approval link expires in 48 hours.',
  `Approve: ${decisionUrl('approve')}`,
  `Reject: ${decisionUrl('reject')}`,
].join('\n');

return [{
  json: {
    ...data,
    notification: {
      recipient,
      sender,
      subject: `FlowPilot ${data.analysis.priority}-priority lead notification`,
      body: notificationBody,
    },
  },
}];

const emailResult = $json;
const prepared = $('Prepare Internal Notification').item.json;

if (emailResult.error || emailResult.success === false) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'EMAIL_ERROR',
        message: 'Lead was processed but the internal notification could not be sent.',
      },
    },
  }];
}

const { notification, draft, approval, lead_id, ...publicWorkflowData } = prepared;
return [{ json: publicWorkflowData }];

