const stored = $json;

if (!stored.id || !stored.created_at) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'PERSISTENCE_ERROR',
        message: 'Lead was analyzed but could not be saved.',
      },
    },
  }];
}

return [{
  json: {
    success: true,
    statusCode: 200,
    lead_id: stored.id,
    created_at: stored.created_at,
    lead: {
      name: stored.name,
      email: stored.email,
      company: stored.company,
      message: stored.message,
      budget: Number(stored.budget),
    },
    analysis: {
      category: stored.category,
      priority: stored.priority,
      lead_score: stored.lead_score,
      short_summary: stored.short_summary,
      recommended_action: stored.recommended_action,
    },
  },
}];

const sheetsResult = $json;
const persisted = $('Sanitize Persistence Result').item.json;
const sheetsFailed = Boolean(sheetsResult.error) || sheetsResult.success === false;

if (sheetsFailed || !persisted?.success || !persisted?.created_at) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'PERSISTENCE_ERROR',
        message: 'Lead was analyzed but could not be fully persisted.',
      },
    },
  }];
}

return [{ json: persisted }];

const persisted = $json;
const parts = String(persisted.lead.name ?? '').trim().split(/\s+/).filter(Boolean);
const firstname = parts.shift() ?? '';
const lastname = parts.join(' ');

return [{
  json: {
    ...persisted,
    crmContact: {
      email: persisted.lead.email,
      firstname,
      lastname,
      company: persisted.lead.company,
    },
  },
}];

const response = $json;
const prepared = $('Prepare HubSpot Contact').item.json;
const statusCode = Number(response.statusCode ?? 0);

const crmError = () => [{
  json: {
    success: false,
    statusCode: 503,
    error: {
      code: 'CRM_ERROR',
      message: 'Lead was persisted but could not be synchronized with CRM.',
    },
  },
}];

if (statusCode < 200 || statusCode >= 300) {
  return crmError();
}

const result = response.body;
if (!result || typeof result !== 'object' || !Array.isArray(result.results)) {
  return crmError();
}

if (result.results.length === 0) {
  return [{
    json: {
      ...prepared,
      crmContact: { ...prepared.crmContact, action: 'create' },
    },
  }];
}

const contactId = result.results[0]?.id;
if (!contactId) {
  return crmError();
}

return [{
  json: {
    ...prepared,
    crmContact: {
      ...prepared.crmContact,
      action: 'update',
      contactId: String(contactId),
    },
  },
}];

const response = $json;
const prepared = $('Determine HubSpot Contact Path').item.json;
const statusCode = Number(response.statusCode ?? 0);
const result = response.body;

if (statusCode < 200 || statusCode >= 300 || !result || typeof result !== 'object' || !result.id) {
  return [{
    json: {
      success: false,
      statusCode: 503,
      error: {
        code: 'CRM_ERROR',
        message: 'Lead was persisted but could not be synchronized with CRM.',
      },
    },
  }];
}

const { crmContact, ...workflowData } = prepared;
return [{ json: workflowData }];
